// ===== NM:module landmarks — gambar aset pengguna sebagai titik menu di venue (Booth: kiri, Galeri: kanan) =====
// Tiap landmark: gambar = sprite bergambar di venue; klik gambar / menu area -> avatar berjalan ke titik (ax,az) di depan gambar.
// Tambah landmark baru: tambahkan satu entri di NMLM + gambar DECO (webp transparan).
(function(){
 DECO.photobooth=['data:image/webp;base64,',1200,800];
 DECO.galerifoto=['data:image/webp;base64,',1200,800];
 const NMLM=[
  {area:'booth',id:'booth0',k:'photobooth',name:'Photo Booth',x:-12.2,z:-9.6,w:7.4,y:-.2,ax:-12.2,az:-8.3},
  {area:'galeri',id:'galeri0',k:'galerifoto',name:'Galeri Foto',x:12.2,z:-9.6,w:7.4,y:-.2,ax:12.2,az:-8.3}
 ];
 // layar Video Ucapan digeser ke tengah-kanan agar tidak menutupi gambar Galeri; titik berdiri video mengikuti
 const SCREEN={x:6.2,z:-9.4},VIDEO={x:6.2,z:-6.6};
 NMLM.forEach(L=>{LAYOUT.push({id:L.id,k:L.k,x:L.x,z:L.z,w:L.w,y:L.y,l:'furn'});const a=AREAS.find(a=>a.id==L.area);if(a){a.x=L.ax;a.z=L.az;a.n=L.name}});
 const sv=LAYOUT.find(o=>o.id=='screen0');if(sv){sv.x=SCREEN.x;sv.z=SCREEN.z}
 {const a=AREAS.find(a=>a.id=='video');if(a){a.x=VIDEO.x;a.z=VIDEO.z}}
 const _ill=illustrate;
 illustrate=function(){const r=_ill.apply(this,arguments);
  try{// pengaturan area lain menimpa AREAS/layout saat illustrate -> pasang lagi
   NMLM.forEach(L=>{const a=AREAS.find(a=>a.id==L.area);if(a){a.x=L.ax;a.z=L.az;a.n=L.name}});
   {const a=AREAS.find(a=>a.id=='video');if(a){a.x=VIDEO.x;a.z=VIDEO.z}}
   if(VS['screen0'])relayout('screen0',SCREEN.x,SCREEN.z);
   const keep=new Set();
   NMLM.forEach(L=>{dc(L.k);relayout(L.id,L.x,L.z,L.w,L.y);const s=VS[L.id];if(s){s.userData.area=L.area;clk.push(s);keep.add(s)}});
   // label bawaan (booth/galeri/video) dihilangkan: gambar booth/galeri sudah bertuliskan nama; label video akan menutupi layar
   const hid=[[NMLM[0].ax,NMLM[0].az-1.2],[NMLM[1].ax,NMLM[1].az-1.2],[VIDEO.x,VIDEO.z-1.2]];
   sc.children.forEach(o=>{if(o.isSprite&&!keep.has(o)&&hid.some(h=>Math.abs(o.position.x-h[0])<.01&&Math.abs(o.position.z-h[1])<.01))o.visible=false});
  }catch(e){console.warn('landmarks',e)}
  return r};
})();
